package ua.edu.nupp.kpp.server;
import java.time.LocalDate;
public class PropertyRequest { private long id,userId,propertyId; private int quantity,timelinessScore; private LocalDate plannedReturnDate; private RequestState status; private double integralIndex; public PropertyRequest(){} public long getId(){return id;} public void setId(long v){id=v;} public long getUserId(){return userId;} public void setUserId(long v){userId=v;} public long getPropertyId(){return propertyId;} public void setPropertyId(long v){propertyId=v;} public int getQuantity(){return quantity;} public void setQuantity(int v){quantity=v;} public int getTimelinessScore(){return timelinessScore;} public void setTimelinessScore(int v){timelinessScore=v;} public LocalDate getPlannedReturnDate(){return plannedReturnDate;} public void setPlannedReturnDate(LocalDate v){plannedReturnDate=v;} public RequestState getStatus(){return status;} public void setStatus(RequestState v){status=v;} public double getIntegralIndex(){return integralIndex;} public void setIntegralIndex(double v){integralIndex=v;} }
